void source_run_vitality_runtime(M &m,std::uint32_t entry,
    SourcePhysicsContactRuntimeAbi &abi,SourcePhysicsContactImage image,FP fp,
    const SourcePhysicsContactRuntimeServices &services,const O &observe) {
    if(image!=SourcePhysicsContactImage::MapPack11&&image!=SourcePhysicsContactImage::TitleUpdate15)
        throw std::runtime_error("Unverified physics contact executable image");
    FpScope scope(fp);WorldState s{m,observe,services,image};s.load(abi);
    try {
        switch(entry) {
case 0xa87e0u:run_a87e0(s);break;
case 0xbbcb0u:run_bbcb0(s);break;
case 0xd7160u:run_d7160(s);break;
case 0xd73e0u:run_d73e0(s);break;
case 0xd7cd0u:run_d7cd0(s);break;
case 0xd7d90u:run_d7d90(s);break;
case 0xd80f0u:run_d80f0(s);break;
case 0xda150u:run_da150(s);break;
case 0x139ff0u:run_139ff0(s);break;
case 0x13be58u:run_13be58(s);break;
case 0x14f5d0u:run_14f5d0(s);break;
case 0x159ef0u:run_159ef0(s);break;
case 0x1ed030u:run_1ed030(s);break;
case 0x1ed0b0u:run_1ed0b0(s);break;

        default:throw std::runtime_error("Required original contact entry unavailable");
        }
    } catch(...) {abi=s.save();throw;}
    abi=s.save();
}
